  str_files_story_title_5205 = "다음엔 반드시!·3",
  str_files_story_title_5301 = "행복한 금·1",
  str_files_story_title_5303 = "행복한 금·2",
  str_files_story_title_5305 = "행복한 금·3",
  str_files_story_des_101 = "나시리스만 「기본 정보 수집표」를 작성하지 않았다, 왜 그녀는 이런 일을 그렇게나 꺼려하는 걸까...?",
  str_files_story_des_103 = "뜻밖에 「나시리스」 2명을 만났다. 설마 이 중 한 명이 항상 말하던 「언니」?! 전혀 구분할 수가 없어...",
  str_files_story_des_105 = "스토리5",
  str_files_story_des_107 = "스토리7",
  str_files_story_des_110 = "스토리10",
  str_files_story_des_201 = "요즘 등이 따가울 정도의 「시선」이 자꾸 느껴진다. 당신은 「그 사람」을 끌어내려고 조잡한 연극을 벌이는데...",
  str_files_story_des_203 = "상대는 의외로 살가운 반응을 보이고 있지만, 강력한 카리스마가 여전히 당신을 쩔쩔매게 만들고 있다. 질문이 있는데 물어봐도 되려나...",
  str_files_story_des_205 = "스토리5",
  str_files_story_des_207 = "스토리7",
  str_files_story_des_209 = "스토리9",
  str_files_story_des_210 = "스토리10",
  str_files_story_des_402 = "스토리2",
  str_files_story_des_404 = "스토리4",
  str_files_story_des_406 = "스토리6",
  str_files_story_des_408 = "스토리8",
  str_files_story_des_501 = "스토리1",
  str_files_story_des_503 = "스토리3",
  str_files_story_des_505 = "스토리5",
  str_files_story_des_507 = "스토리7",
  str_files_story_des_509 = "스토리9",
  str_files_story_des_510 = "스토리10",
  str_files_story_des_602 = "성주님 딸과 어울리는 건 쉽지 않은 일이다. 당신은 리더로서의 카리스마를 보여주려고 하는데...",
  str_files_story_des_604 = "카렌은 자신의 입장에 미묘한 「갈등」이 있는 것 같다. 「이해」를 잘 못하는 당신은 어떻게 해야 그녀의 마음의 문을 열 수 있을 것인가...",
  str_files_story_des_606 = "스토리6",
  str_files_story_des_608 = "스토리8",
  str_files_story_des_609 = "스토리9",
  str_files_story_des_610 = "스토리10",
  str_files_story_des_802 = "스토리2",
  str_files_story_des_804 = "스토리4",
  str_files_story_des_806 = "스토리6",
  str_files_story_des_901 = "스토리1",
  str_files_story_des_903 = "스토리3",
  str_files_story_des_905 = "스토리5",
  str_files_story_des_907 = "스토리7",
  str_files_story_des_910 = "스토리10",
  str_files_story_des_1002 = "스토리2",
  str_files_story_des_1004 = "스토리4",
  str_files_story_des_1006 = "스토리6",
  str_files_story_des_1008 = "스토리8",
  str_files_story_des_1009 = "스토리9",
  str_files_story_des_1102 = "정해진 검열의 날은 아니지만, 당신은 큰 압박감을 느낀다. 일루미나 군단장 중 한명인 시로나가 콜로서스 운영을 지적한다고?! 제발 모든 것이 순조롭길...",
  str_files_story_des_1104 = "콜로서스와 당신에게 많은 심혈을 기울인 시로나에겐 「자신만의 이유」가 있는 것 같다. 어쩌면 그녀는 당신에게서 자신이 바라던 모습을 본 것인지도 모른다...",
  str_files_story_des_1106 = "스토리5",
  str_files_story_des_1108 = "스토리7",
  str_files_story_des_1110 = "스토리10",
  str_files_story_des_1201 = "「작은 일」 때문에 콜로서스에 엄청나게 큰 다툼소리가 들린다! 당신이 원하든 원하지 않든, 가서 「중재인」이 되어줘야 할 것 같다...",
  str_files_story_des_1203 = "네메시스 씨는 「공평과 정의」에 너무 집착한다. 아무래도 시간을 내 네메시스 씨에게 어떤 남모르는 사정이 숨겨져 있는지 이야기하며 알아봐야 할지도 모르겠다...",
  str_files_story_des_1205 = "스토리5",
  str_files_story_des_1207 = "스토리7",
  str_files_story_des_1210 = "스토리10",
  str_files_story_des_1302 = "스토리2",
  str_files_story_des_1304 = "스토리4",
  str_files_story_des_1306 = "스토리6",
  str_files_story_des_1308 = "스토리8",
  str_files_story_des_1309 = "스토리9",
  str_files_story_des_1310 = "스토리10",
  str_files_story_des_1402 = "성주님께서 직접 콜로서스 시찰을 오신다고?! 정신없는 당신은 시작부터 지각을 하고 말았다. 앞으로 절대로 더는 실수가 없어야 한다. 최대한!",
  str_files_story_des_1404 = "「인자한」 성주님이 다시 흉흉한 기세로 당신의 앞에 다가왔다. 이게 대체 어떻게 된 일일까?! 콜로서스의 책임자로서 당신은 「기대」와 「실망」이 공존하는 눈빛을 다시금 느꼈다...",
  str_files_story_des_1406 = "스토리6",
  str_files_story_des_1408 = "스토리8",
  str_files_story_des_1409 = "스토리9",
  str_files_story_des_1410 = "스토리10",
  str_files_story_des_1701 = "스토리1",
  str_files_story_des_1703 = "스토리3",
  str_files_story_des_1705 = "스토리5",
  str_files_story_des_1707 = "스토리7",
  str_files_story_des_1802 = "음악 라이브 초대장? 휴식 시간을 포기하고 이상한 활동에 참여할까 망설이고 있는데, 강한 노크 소리가 들려온다...",
  str_files_story_des_1804 = "약속의 날이 되었다. 레지나의 라이브는 어떤 모습일까? 은근히 불안해지는데...",
  str_files_story_des_1806 = "스토리6",
  str_files_story_des_1808 = "스토리8",
  str_files_story_des_1809 = "스토리9",
  str_files_story_des_1810 = "스토리10",
  str_files_story_des_1901 = "스토리1",
  str_files_story_des_1903 = "스토리3",
  str_files_story_des_1905 = "스토리5",
  str_files_story_des_1907 = "스토리7",
  str_files_story_des_1910 = "스토리10",
  str_files_story_des_2101 = "스토리1",
  str_files_story_des_2103 = "스토리3",
  str_files_story_des_2105 = "스토리5",
  str_files_story_des_2107 = "스토리7",
  str_files_story_des_2201 = "스토리1",
  str_files_story_des_2203 = "스토리3",
  str_files_story_des_2205 = "스토리5",
  str_files_story_des_2301 = "스토리3",
  str_files_story_des_2303 = "스토리5",
  str_files_story_des_2305 = "스토리7",
  str_files_story_des_2307 = "스토리9",
  str_files_story_des_2310 = "스토리10",
  str_files_story_des_2501 = "평범한 하루이자, 카론의 「항의서」가 여러 통 날아온 날이기도 했다... 아무래도 찾아가서 얘기를 나눠야겠다...",
  str_files_story_des_2503 = "카론과 정상적으로 소통할 방법이 전혀 없다... 기회가 되면 더 많은 정보를 수집해보자. 「광기」의 근원을 알게 될지도...",
  str_files_story_des_2505 = "스토리5",
  str_files_story_des_2507 = "스토리7",
  str_files_story_des_2509 = "스토리9",
  str_files_story_des_2510 = "스토리10",
  str_files_story_des_2602 = "스토리2",
  str_files_story_des_2604 = "스토리4",
  str_files_story_des_2606 = "스토리6",
  str_files_story_des_2608 = "스토리8",
  str_files_story_des_2609 = "스토리9",
  str_files_story_des_2610 = "스토리10",
  str_files_story_des_2801 = "뭔가 안 좋은 일이 생길 것만 같은 느낌이 드는데... 대체 뭘까? 아, 저 멀리 있는 건 라파엘? 왜 미친듯이... 손을 흔들지?",
  str_files_story_des_2803 = "라파엘이 추구하는 의료 수단 개선은 정말이지... 머리가 아프다. 오늘은 라파엘에게 「당하지」 않았으면 좋겠다... 아니면 당신마저도 항의서를 쓰게 될지도 모르니 말이다...",
  str_files_story_des_2805 = "스토리5",
  str_files_story_des_2807 = "스토리7",
  str_files_story_des_2809 = "스토리9",
  str_files_story_des_2810 = "스토리10",
  str_files_story_des_2902 = "스토리2",
  str_files_story_des_2904 = "스토리4",
  str_files_story_des_2906 = "스토리6",
  str_files_story_des_2908 = "스토리8",
  str_files_story_des_2909 = "스토리9",
  str_files_story_des_2910 = "스토리10",
  str_files_story_des_3202 = "스토리2",
  str_files_story_des_3204 = "스토리4",
  str_files_story_des_3206 = "스토리6",
  str_files_story_des_3301 = "질문: 당신은 함께 지내는 「오래된 친구」를 얼마나 알고 있는가? 그녀의 솔직한 생각을 알고 있는가? 어쩌면 그 답은 아직 깊은 곳에 있을지도 모른다...",
  str_files_story_des_3303 = "바이스와 어떤 「설문조사」를 하기로 했는데, 테스트 같은 느낌이 든다. 불안한 마음을 가지고 약속한 장소로 갔다. 어떤 테스트든지 바이스가 좀 봐줬으면 좋겠는데...",
  str_files_story_des_3305 = "스토리6",
  str_files_story_des_3307 = "스토리8",
  str_files_story_des_3310 = "스토리10",
  str_files_story_des_3501 = "최근 에호의 배달 시간 정확율이 많이 떨어졌군. 무슨 이유라도 있는 걸까? 얘기를 한 번 해보자...",
  str_files_story_des_3503 = "에호가 길치였구나... 일이 정말 쉽지 않겠네. 그래서 지도를 베끼는 것이 정말로 기억에 도움이 되는 거야...?",
  str_files_story_des_3505 = "스토리5",
  str_files_story_des_3602 = "스토리1",
  str_files_story_des_3604 = "스토리3",
  str_files_story_des_3606 = "스토리5",
  str_files_story_des_3608 = "스토리7",
  str_files_story_des_3610 = "스토리10",
  str_files_story_des_3802 = "그로누 씨가 최근 콜로서스 보수 작업을 열심히 하는 것이 큰 관심과 열정이 있는 것 같다. 오늘은 공식적인 첫 만남인데 어떤 성격을 가지고 있을까?",
  str_files_story_des_3804 = "그로누 씨는 게임을 무척 좋아하는 것 같다... 그 부분이 일상적인 업무에 영향을 주지 않았으면 좋겠는데, 그렇지 않으면 곤란하다...",
  str_files_story_des_3806 = "스토리6",
  str_files_story_des_3808 = "스토리8",
  str_files_story_des_3809 = "스토리9",
  str_files_story_des_3810 = "스토리10",
  str_files_story_des_4001 = "스토리1",
  str_files_story_des_4003 = "스토리3",
  str_files_story_des_4005 = "스토리5",
  str_files_story_des_4007 = "스토리7",
  str_files_story_des_4101 = "큰 집회가 있을 때마다 Ms. 블랑은 더 바쁘다. 한번 가볼까? 도울 수 있다면 더 좋겠지. 「방해」가 되지는 않아야 할 텐데...",
  str_files_story_des_4103 = "정말로 방해가 됐는지, Ms. 블랑이 더 바빠졌다... 만회할 기회가 있지 않을까?",
  str_files_story_des_4105 = "스토리5",
  str_files_story_des_4107 = "스토리7",
  str_files_story_des_4402 = "스토리2",
  str_files_story_des_4404 = "스토리4",
  str_files_story_des_4406 = "스토리6",
  str_files_story_des_4408 = "스토리8",
  str_files_story_des_4601 = "스토리1",
  str_files_story_des_4603 = "스토리3",
  str_files_story_des_4605 = "스토리5",
  str_files_story_des_4701 = "최근 조르아의 행적이 좀 이상하다... 떠돌아다니고, 보였다가 사라지는 것이 마치... 뭔가를 관찰하는 건가?",
  str_files_story_des_4703 = "조르아는 히이로 군단장님에게 「남다르게」 의지하고 있었다... 그녀의 이야기를 들어보고 싶은데, 조르아가 말해줄 생각이 있을까?",
  str_files_story_des_4705 = "스토리5",
  str_files_story_des_4801 = "콜로서스 책임자로서 일상적인 업무 외에 「정보 수집」도 임무 중 하나이다. 이번에 디나와 함께할 기회를 이용해야 할 것 같은데?",
  str_files_story_des_4803 = "역시 상단 일은 그렇게 쉽지 않아... 디나와 얼마나 멀리 왔는지는 모르겠지만 정보 수집은 고사하고 서있을 힘마저 사라지기 직전이다...",
  str_files_story_des_4805 = "스토리5",
  str_files_story_des_4807 = "스토리7",
  str_files_story_des_4902 = "스토리2",
  str_files_story_des_4904 = "스토리4",
  str_files_story_des_4906 = "스토리6",
  str_files_story_des_5001 = "스토리1",
  str_files_story_des_5003 = "스토리3",
  str_files_story_des_5005 = "스토리5",
  str_files_story_des_5101 = "스토리1",
  str_files_story_des_5103 = "스토리3",
  str_files_story_des_5105 = "스토리5",
  str_files_story_des_5201 = "스토리2",
  str_files_story_des_5203 = "스토리4",
  str_files_story_des_5205 = "스토리6",
  str_files_story_des_5301 = "항의서가 가장 많이 들어오는 문제의 인물을 꼽자면 그중 하나는 분명히 조무일 것이다. 아무 데나 노점을 차리고 마구잡이로 홍보하는 그의 수법은 너무나 곤란하다. 오늘은 안 만났으면 좋겠는데...",
  str_files_story_des_5303 = "조무는 대체 왜 그렇게 「열심히」 돈을 버는 걸까? 도박 같은 걸 하는 거 같지는 않은데, 배후에 또 다른 이야기가 있을지도?",
