  str_files_story_title_30131 = "버터 향 추억",
  str_files_story_title_30128 = "의사의 초심",
  str_files_story_title_30130 = "황금 같은 시간",
  str_files_story_title_30129 = "화려한 세계",
  str_files_story_title_30132 = "또 한 번의 부름",
  str_files_story_title_35042 = "일의 의미",
  str_files_story_title_30133 = "후일담: 낙원에 이르러",
  str_files_story_des_10101 = "[추가 예정]",
  str_files_story_des_10201 = "연이은 전투에 다들 한계에 부딪힌 것 같다. 가장 큰 적은 암귀가 아닌 피로일지도...",
  str_files_story_des_10202 = "안젤의 요청으로 콜로서스에 있는 또 다른 방의 진정한 용도를 알아낼 수 있었다. 안젤의 다른 면모 또한 말이다...",
  str_files_story_des_10203 = "「불쌍한」 도브는 제대로 쉴 수 없는 모양이다. 뭔가 방법을 생각해 주는 게 좋을 것 같다. 비록 도브는 게으르지만, 그래도 아직 일은 하고 있다... 적어도 본인은 그렇게 말한다.",
  str_files_story_des_10204 = "당신은 달변가인 조르아의 요청을 들어줄 수밖에 없었다. 비록 조르아가 원하는 결과는 아니었지만, 그녀는 결국 목적을 달성할 수 있었다...",
  str_files_story_des_10301 = "스카이워커호가 28호 지하성으로 보내진 동안, 카론은 당신에게 28호 지하성과 일루미나 연방에 대한 것을 알려줬다. 이는 당신이 이 세계를 이해하는 데 큰 도움이 되었다.",
  str_files_story_des_10302 = "멘델슨 사건이 끝난 뒤, 당신은 히이로와 함께 스카이워커호에서 시간을 보내고 있다. 어쩌면 아이테르에게 호기심을 느껴서인지, 히이로는 오랜만에 평소에는 잘 꺼내지 않는 이야기를 들려주었다.",
  str_files_story_des_10303 = "어쩌다 여유 시간이 생기자, 바이스는 콜로서스의 각종 데이터를 측정하기 시작했다. 설마 콜로서스에 무슨 짓이라도 하려는 걸까? 설마 아니겠지...",
  str_files_story_des_10304 = "카렌과 바이스가 백야성에서의 생활에 대해 이야기를 나누더니, 백야성의 통치 질서에 대해 「우호적인」토론을 벌였다.",
  str_files_story_des_10305 = "잠깐 떠나 있었을 뿐이지만, 자난성의 일상 업무는 이미 혼란에 빠졌고, 모두가 망설일 뿐 속수무책인 상황이다. 이 소식을 들은 비비안은 서둘러 자난성으로 가서 문제를 해결했고, 당신은 그녀의 「무서운」 능력을 보게 되었다...",
  str_files_story_des_10306 = "정체불명의 누군가가 콜로서스의 손상된 부분을 수리했다. 그녀의 목적은 무엇일까? 그저 소소한 놀이였을까? 아니면 일루미나 연방의 최신 장비 테스트!?",
  str_files_story_des_10307 = "디바우러호에서 만났었던 정체 불명의 사람, 「파우스트」가 다시 콜로서스에 나타났다. 그리고 가지고 온 건 자신의 「배경 조사 보고서」...?",
  str_files_story_des_10308 = "헤븐즈 밸리로 향하기 전, 당신과 바이스는 함께 병원에 있는 비비안을 보러 가기로 했다. 그러나 병원으로 가던 도중 바이스의 지갑이 사라진 것을 발견했다... 설마 도둑맞은 걸까?",
  str_files_story_des_20100 = "[추가 예정]",
  str_files_story_des_20101 = "그로누가 갑자기 당신에게 함께 콜로서스 정비를 하자더니, 자신과 대결 놀이를 하자고 요청했다. 만약 그녀에게 진다면 그로누는 콜로서스에 「불필요한」 무언가를 할 것이라고 말했다...",
  str_files_story_des_20200 = "히이로는 자난성 유람을 요청했다. 그녀는 당신에게 이상한 쪽지를 건내며 그들 일루미나 장군과 「쪽지」에 얽힌 이야기를 들려줬다.",
  str_files_story_des_20201 = "일루미나의 회의가 끝난 후, 바튼이 갑자기 당신에게 상황을 설명하기 시작했고, 이 모든 원인은 당신이 다른 세 장군에게 「먹힐」까 봐 걱정해서라고 하는데...?",
  str_files_story_des_20202 = "당신은 바튼에게 그저 「전투」의 의미에 대해서만 물어보려고 했지만, 바튼은 억지로 워게임을 시작해 버렸다. 바튼이 황당한 방법으로 승리를 선언한 후, 그는 「승리」야말로 「전투」의 의미라고 말했다.",
  str_files_story_des_20203 = "당신은 최근 잠을 푹 잘 수 없었다. 이에 시로나는 자신만의 방법으로 이 문제를 해결해 주겠다고 했다. 시로나의 방법은 비록 조금 난폭했지만, 단순하고 효과적이었다.",
  str_files_story_des_20204 = "방으로 돌아온 당신은 누군가 알 수 없는 쪽지를 남긴 것을 발견했고, 감응 능력을 통해 히이로 군단장과 관계가 있다는 사실을 알게 되었다. 하지만 히이로와의 대치 속에서 점차 진실이 드러나기 시작했다.",
  str_files_story_des_20205 = "콜로서스 안, 레이스가 왠지 무슨 일인지 고민에 빠져 있었다. 그러나 당신이 가까이 가자 분위기가 이상하게 변했고, 어둠 속의 「추격」이 펼쳐지기 시작했다.",
  str_files_story_des_20300 = "허황된 기쁨에 빠져들 것인가? 아니면 진실의 고통에 만족할 것인가? 「지난날의 꿈」이 두 팔을 벌리자 진리의 결사 일각을 볼 수 있었다.",
  str_files_story_des_20301 = "만약 당신이 「무슨 일이 있어도 내일이 어떤 모습일지 알고 싶다」면, 빅토리아는 당신의 선택을 존중할 것이다...",
  str_files_story_des_20302 = "파우스트의 흰 상자를 돌보는 것은 쉽지 않다. 특히 그 녀석은 고양이 같은 성격까지 가지고 있다.",
  str_files_story_des_20303 = "진정한 미식의 왕은 초대용량의 고기이든, 덩굴이든, 모래든, 흙이든 모든 것을 삼켜버린다. 하지만 유일하게 당근은...",
  str_files_story_des_20304 = "콜로서스에 가만히 서 있는 나일즈는 겉보기에는 생기가 없고 허약해 보이지만, 그의 눈빛은 무엇에도 흔들리지 않는 평온함이 깃들어 있다. 어쩌면 겉으로만 그렇게 보일 수도 있지만...",
  str_files_story_des_20400 = "불현듯 조종사는 카페로 가 코놀리의 솜씨를 맛보기로 한다. 가는 도중 레오나가 휴라드와 말싸움을 하다가 몸싸움으로 번진 상황을 마주하게 된다. 이 둘의 충돌은 콜로서스에서 일상이 된 듯하다. 혼란을 해결하기 위해 조종사는 코놀리에게 도움을 요청했다.",
  str_files_story_des_20401 = "당신은 잠을 자다가 「이상한 소리」에 깨서 수면 부족과 긴장에 시달리고 있었다. 이 말을 듣자 코놀리는 자신이 도와주겠다고 했고, 자신의 경험을 바탕으로 판단을 내렸다. 그리고 그 「이상한 소리」의 정체가 밝혀지는데...",
  str_files_story_des_20402 = "휴라드는 당신을 보자 매우 놀랐고, 당신이 백야성에 가지 않았다는 것을 알게 되자 클레이튼에 대한 태도가 더욱 나빠지고 말았다. 휴라드와 클레이튼의 사이가 나쁘다는 것을 알게 된 당신은 그에게 자초지종을 물었고, 이에 휴라드는 이야기를 시작했다...",
  str_files_story_des_20403 = "당신은 한밤중에 「그림자 늑대」가 당신의 방에 몰래 들어온 것을 발견했다. 이에 휴라드에게 따지러 간 당신은 「그림자 늑대」를 치워달라고 했지만, 그는 「할 수 없다」고 하는데?",
  str_files_story_des_20404 = "제인은 증언자으로서 모든 것을 묵묵히 지켜봤지만, 주변의 사람들도 그녀의 차가우면서도 따뜻한 마음을 지켜보는지는 전혀 몰랐다.",
  str_files_story_des_20405 = "레오나는 평소에 그녀의 작은 용 선스톤과 그림자처럼 붙어 떨어지지 않는다. 하지만 최근, 선스톤이 레오나 곁에 붙어 있는 것 같지 않다. 그와 동시에 선스톤처럼 사라진 것이 또...",
  str_files_story_des_20500 = "「격투 응원」 콘서트! 록, 열정, 열창! 현장 관객 모집 중! 조무에게 신청하세요.",
  str_files_story_des_20501 = "주제도 모르는 바바라를 철저히 짓뭉개려면, 레지나의 노래는 반드시 완벽해야 하며, 모두에게 전율을 선사해야만 한다!",
  str_files_story_des_20502 = "타이니의 최신 발명품에는 「레지나의 극한 데스 록 모닝콜 기계」, 「특급 볶음밥 로켓」, 「쿨 스포트라이트」 등이 있다.",
  str_files_story_des_20503 = "오디의 스케줄이 가득 차버리자, 거대한 스트레스가 그녀를 거의 파묻어버렸다. 이대로 가다간...",
  str_files_story_des_20504 = "아름다운 노을빛이 작은 꿈처럼 투명한 병안에서 반짝인다. 바바라는 좋아서 당신에게 최고의 답례를 한다.",
  str_files_story_des_20506 = "「세상에 공짜 점심은 없다」. 조무의 신비한 선물은 싸고 실속있어 보이지만 사실 가격은 이미 표시되어 있다.",
  str_files_story_des_20600 = "[추가 예정]",
  str_files_story_des_20601 = "한때 북방의 왕궁에서 혼자 살던 루이스는 사방을 여행하던 노아와 만나게 되었다. 이 이야기는 두 사람이 서로를 알아가는 이야기이다.",
  str_files_story_des_20602 = "루이스는 불면증에 시달리는 당신을 위해 새로운 동화를 들려주었고, 특별히 수제 푸딩도 가져왔다. 하지만 달콤한 향기가 나는 푸딩이 뭔가 수상한데...",
  str_files_story_des_20603 = "베들레헴은 당신에게 루이스와 노아가 열심히 공부하고 있는지 확인해 보라고 했다. 그러나 예상치 못한 「불똥」이 당신에게 튀고 마는데...",
  str_files_story_des_20604 = "당신은 나시리스에게 긴장을 풀어주는 주는 꽃을 줄 수 있냐고 물었고, 그녀는 당신이 원하는 대로 수많은 꽃을 준비했다. 다만 그 '수'에 뭔가 오해가 있었던 것 같은데...",
  str_files_story_des_20605 = "오로리안의 능력에 대한 데이터를 연구하고 싶었던 당신은 「무엇이든 안다」고 자부하는 노아에게 이를 물었다. 노아는 비록 자신의 능력을 사용해 「완벽」한 데이터를 제공했지만, 그 결과는 그리 「완벽」하지 않은 듯하다...",
  str_files_story_des_20606 = "당신을 도와 청소를 하려던 노아는 갑자기 결벽증이 발작했고, 온종일 작은 얼룩 하나 때문에 반복해서 벽을 닦고 있었다. 이에 당신은 직접 나서기로 했다.",
  str_files_story_des_20607 = "오피나는 콜로서스에서 사람들과 더 잘 어울리기 위해 '남이 자신의 뿔을 만질' 때 느끼는 위화감에 익숙해지도록 단련할 것을 결심한다. 이를 위해 조종사를 연습 상대로 찾았다.",
  str_files_story_des_20700 = "[추가 예정]",
  str_files_story_des_20701 = "당신은 소문 속의 「번쩍번쩍 뛰는 사람」을 찾고 있었고, 마침 봄버 존과 라비가 논쟁을 벌이고 있었다. 두 사람은 당신을 붙잡고 기괴한 판결을 부탁했고, 당신은 지금까지 찾고 있던 「번쩍번쩍 뛰는 사람」이 누구인지 알게 되는데...",
  str_files_story_des_20702 = "마지는 매우 조급하게 뭔가를 찾고 있다. 하지만 늘 수줍어하던 그녀가 많은 곳을 둘러봐야 분실물을 찾을 수 있다는 소리를 듣자, 놀랍게도 그녀는...",
  str_files_story_des_20800 = "[추가 예정]",
  str_files_story_des_20801 = "에이미는 정식 심판기사처럼 콜로서스를 순찰하고 모두의 고민을 해결해 주고 싶어 한다. 그녀는 무척 노력하고 있지만, 결과는 그다지 좋지 않은 듯하다. 이에 당신을 초대하는데...",
  str_files_story_des_20802 = "콜로서스에 큰 사건이 발생한 것 같다! 백야성의 대심판관님이 직접 조사를 하러 오다니, 대체 무슨 일이 생긴 거지...",
  str_files_story_des_20803 = "미제니가 뭔가를 결정하는 데, 이번 결정 가격은... 좀 이상한 것 같다?",
  str_files_story_des_20900 = "[추가 예정]",
  str_files_story_des_20901 = "라파엘이 콜로서스의 비밀을 발견했다고? 게다가 콜로서스를 치료하려고 한다고? 알고 보니 라파엘은 콜로서스와 비슷한 동료를 치료한 적이 있었다고 한다...",
  str_files_story_des_20902 = "우리엘은 화염을 다룰 수 있지만, 종종 비관적인 생각에 빠지곤 한다. 과연 그녀의 마음을 달래줄 수 있을까?",
  str_files_story_des_20903 = "「때론 느리게 가는 게 안정적이고 더 빠른 길이다」 가브리엘의 말에 당신은 빠져들었다. 하지만 때로는 잠깐 쉬는 것도 정말 좋다.",
  str_files_story_des_20904 = "우연한 기회에 여명 크리스탈을 미카엘에게 선물하니 소녀의 평온한 마음에 풍랑이 일어난 것 같다.",
  str_files_story_des_21000 = "콜로서스에서 돌연 기묘한 시 선정 이벤트가 시작되었다. 심사위원으로 뽑힌 당신은 누구의 시를 더 좋아할까?",
  str_files_story_des_21001 = "당신은 키팅 성가대의 4인방에게 「대체 누가 남자애고 누가 여자애인지」 물었지만, 네 사람은 당신이 그들의 시험을 통과해야만 답을 알려주겠다고 한다.",
  str_files_story_des_21002 = "키팅은 솔라드가 휴식을 취하고 있는 틈을 타 그의 귀에 꽃을 꽂았고, 솔라드는 이 일을 두고 화를 내며 당신에게 처리를 요구했다. 이에 모두의 노력 끝에 특별한 「사건 기록」이 만들어졌다...",
  str_files_story_des_21003 = "당신은 키팅 성가대에게 먼저 대화를 시도했고, 「그들이 말하는 방식을 바꿀 수 있기를 바란다」고 말했다. 당신의 노력 끝에 몇몇 아이들은 당신의 깊은 마음씨를 알게 되었지만, 거절당했다.",
  str_files_story_des_21004 = "한밤 중에 들려오는 은은한 선율, 무슨 일인지 원한의 울음 소리가 함께 들려오더니 절정에서 뚝 그쳤다.",
  str_files_story_des_21005 = "콜로서스의 구석에 누군가 이상한 「하얀 꽃」을 「심었다」. 조사해보니 우라이아가 한 것 같다. 하지만... 왜일까?",
  str_files_story_des_21100 = "이스타반 클랜이 3통의 편지를 보내왔는데 그중 하나를 들고 만나자고 한다. 모든 정보를 조사하고 기록한 후 최종 선택을 하는데...",
  str_files_story_des_21101 = "클레이튼은 곡절을 에둘러 표현하는 방식으로 당신에게 「예언 게임」을 요청했다. 그리고 마지막이 되어서야 당신은 그의 진짜 목적을 알게 되는데...",
  str_files_story_des_21102 = "클레이튼이 「디보리 모험도」를 선물로 받은 후, 당신에게 함께 해보자고 요청했다. 그리고 「그와 모험도」에 대한 기묘한 이야기를 들려주기 시작했는데...",
  str_files_story_des_21104 = "술 한 잔 마셔! 거짓말의 맛은 달콤하면서도 부드럽습니다. 「충성심과 성실」의 맛은 이처럼 쓰디씁니다.",
  str_files_story_des_21105 = "카페가 엉망진창이 되어버렸고, 캐비닛 속의 음식은 온데간데없이 사라져버렸다. 이 소식을 전한 세르고는 가장 먼저 현장에 도착한 사람이자 가장 의심스러운 사람이었다...",
  str_files_story_des_21106 = "파티, 파시와 함께 숨바꼭질을 즐겼던 기억을 떠올렸다. 그 애들의 노래는 정말 이상하고 기괴했지만, 마음이 편안해질 때도 있었다.",
  str_files_story_des_21200 = "법정? 심판? 일루미나 연방 지원 본부에 범죄자가 나타났다? 진실은 대체 무엇일까?",
  str_files_story_des_21201 = "비비안은 항상 바쁘다. 콜로서스에서도 마찬가지다. 그러나 고생한 자신을 위한 음료를 받는 순간, 그녀는 이상한 반응을 보이기 시작했다...",
  str_files_story_des_21202 = "당신에게 고마움을 전하기 위해, 비비안은 「큰 선물」을 준비했다고 한다. 그녀의 친절한 호의를 다 먹을 수 있을까?",
  str_files_story_des_21204 = "항상 「화려한 자태」를 뽐내던 카론이 최근 갑자기 부쩍 수상해졌다. 왠지 그는 파이어플라이에 관심을 보이는 것 같은데, 과연 그 이유는 무엇일까...",
  str_files_story_des_21205 = "우연히 바이스를 만났다가 그녀가 어려운 계획을 실행하고 있다는 걸 발견했다. 그녀의 계획을 도와줄 수 있을까?",
  str_files_story_des_21206 = "일루미나 연방의 감찰관이 갑자기 당신에게 의뢰한다고 한다. 그런데 의뢰할 내용이 선물 하나를 전달하는 것뿐? 정말 이것뿐일까?",
  str_files_story_des_21207 = "필리시가 되었든, 유미가 되었든, 치즈는 그 애들의 약점이다. 만나기만 하면 미친듯이 날뛰는데 치즈가 대체 무슨 짓을 한 걸까?",
  str_files_story_des_21300 = "매주, 솔라드는 한 시간씩 「사라진다」. 대체 무엇을 하러 가는 것일까?",
  str_files_story_des_21301 = "나딘은 갑자기 당신을 위해 뭐라도 하고 싶다고 했고, 당신은 그녀의 노력과 호의에 감동했다. 그러나 그녀가 당신에게 사과하면서 그 이유를 알게 되는데...",
  str_files_story_des_21302 = "당신은 Ms. 블랑의 「안내자」의 신분에 호기심이 생겼다. 하지만 오히려 「조종사」에 대한 Ms. 블랑의 호기심을 불러일으키게 되었고, 이에 서로에 대한 기묘한 비교가 펼쳐졌다.",
  str_files_story_des_21303 = "카렌은 「파이어플라이 운반자」를 가지고 온 후, 당신을 키워 준 이 「어머니」에 대해 상당한 관심을 가지게 되었다. 그리고 마지막에는 당신이 감응해서 보았던 「그녀의 어머니에 대한 기억」의 이야기를 들려주었다...",
  str_files_story_des_21304 = "당신은 콜로서스에서 한가롭게 돌아다니며 솔라드의 옆을 지나가다가 호출당했다...",
  str_files_story_des_21400 = "「사막의 끝」은 대체 어디이며, 망명 대열은 또 어디로 가는 것일까?",
  str_files_story_des_21401 = "전설 속의 「천재지변의 악마」, 온갖 못된 짓을 저지르며, 지나가는 곳마다 천재지변 같은 재앙을 일으킨다고 한다. 그녀에게 걸린 현상금은 무려 5억이다.",
  str_files_story_des_21402 = "초조해 하는 카프카, 망연자실한 조종사, 이 모든 것은 프란츠가 실종됐기 때문이다. 이렇게 큰 콜로서스에 그 「그 충성스러운 작은 검은 개」는 대체 어디로 간 걸까?",
  str_files_story_des_21403 = "크면 좋고, 높으면 강하고, 무거우면 힘이 세다. 1kg의 차이도 참을 수 없는 대실패다. 치욕을 씻기 위해 소크는 다시 쿠마에게 도전하는데...",
  str_files_story_des_21404 = "조잡한 가짜를 잔뜩 사버린 렉커는 조무를 찾아갔지만 자신도 모르는 새에 또다시 조무에게 속아 이상한 신제품을 사게 되었다. 이번엔 조종사도 그를 구할 수가 없었는데...",
  str_files_story_des_21500 = "미자드는 콜로서스에 잠입한 「고위 암귀」를 발견하고 카페에 가두었다. 당신들은 이 암귀로부터 중요한 정보를 묻기 위해 몇몇 「심문 전문가」를 찾았고, 결국 알게 된 것은...",
  str_files_story_des_21501 = "베니와 쿠로는 자신들 중 누가 더 강한지 당신에게 「사이좋게」 물었다. 둘의 질문에 당신은 마침내 마음속 생각을 털어놓았다. “\"왜 굳이 우열을 가리려고 하는 거야? 팀이란 단점을 보완하는 rj 아냐?\"",
  str_files_story_des_21502 = "점점 거세지는 항의로 어쩔 수 없이 당신은 미자드에게 그녀가 다른 사람들을 「불편하게」 만드는 행동에 대해 이야기해야만 했다. 하지만 마지막엔 왜인지 당신이 모두를 대신해서 미자드에게 맞서는 것처럼 변해버렸다...",
  str_files_story_des_21503 = "엘시의 방에서 항상 비밀스러운 소리가 난다. 이를 파악하기 위해 당신이 용기를 내서 묻자, 그녀는 당신을 자신의 방에 데려가기로 한다...",
  str_files_story_des_21504 = "와타리는 당신이 보낸 선물을 받았는데, 그것이 그가 의사였던 기억을 떠올리게 한 것 같았다.",
  str_files_story_des_21600 = "마음속으로 그리워하는 것을 보여주는 이상한 테이프, 테사, 샤리, 아이리나는 어떻게 받아들일까?",
  str_files_story_des_21601 = "테사는 당신이 보낸 루미나 휘슬캔디을 받고 불안한 기억을 떠올리게 되는데...",
  str_files_story_des_21603 = "아이리나는 새 치마를 사고 싶었지만, 여러 이유로 살 수 없었다. 알고 보니 이 소녀는 생각보다 무거운 「저주」를 짊어지고 있었다...",
  str_files_story_des_21604 = "샤리가 뭔가 할 말이 있는 것 같다. 그녀는 자신의 할아버지의 「죽음에 대한 비밀」을 알아내기 위해 계속 노력하고 있다. 하지만 백야성의 천사 가브리엘과 그 일이 무슨 관계가 있는 걸까?",
  str_files_story_des_21700 = "세 이야기와 세 사람, 세 이야기와 한 사람, 대체 하나일까 셋일까? 아니면...?",
  str_files_story_des_21701 = "스칼렛이 당신에게 이상한 이야기를 들려준다. 하지만 이야기와 상관없이 이 이야기에 대한 스칼렛의 태도도 의미심장한데...",
  str_files_story_des_21702 = "베벌리는 그녀의 선조 이야기, 귀족 정신에 대해 이야기했다. 당신은 그 귀족 정신을 존경하면서도 한편으론 뭔가 이상하다고 느끼게 되는데...",
  str_files_story_des_21703 = "콘스탄틴이 북방의 암귀 사냥 이야기를 들려준다. 하지만 이번 사냥은 모든 지역마다 이상함이 가득하다...",
  str_files_story_des_21800 = "사메야마가 갑자기 레디젤 렌치에서 주최하는 행사에 당신을 초대하며, 도엔을 돌봐주라는 암시를 남겼다. 알고 보니 이 모든 것은 당신들을 환영하기 위한 것이었다.",
  str_files_story_des_21801 = "이브는 왜 한밤중에 「화약」, 「유황」 같은 걸 찾고 있는 거지? 대체 뭘 하려고...",
  str_files_story_des_21802 = "레디젤 렌치를 대표하는 물건에 대해 대장인 사메야마가 갑자기 질문했다. 이야기해보니 사메야마가 누군가를 위한 선물을 준비하려고 한다는 것을 알게 되었다.",
  str_files_story_des_21803 = "도엔에게 최근 뭔가 고민이 있는 것 같은데 도와주러 가보자...",
  str_files_story_des_21900 = "밀월의 약속이 다가왔다. 「이름 없는 이」여, 좋은 책을 택해서 함께 달빛 아래 독서의 시간을 갖자.",
  str_files_story_des_21901 = "악몽은 계속해서 베릴의 마음을 휘감고 있다. 오직 책을 읽을 때에만 그녀는 순간의 평온을 느낄 수 있다...",
  str_files_story_des_21902 = "술잔 속의 사람은 당신의 눈을 바라보지만, 당신은 그저 닿을 수 없는 머나먼 사람만을 바라볼 뿐이다.",
  str_files_story_des_21903 = "오늘 밤 8시 30분, 라드 얀 공연장, 세상에서 가장 신비하고 아름다우며, 위대한 교향시가 당신을 기다리고 있다!",
  str_files_story_des_23001 = "당신은 우연히 방금 싸움에서 돌아온 디나와 마주쳤고, 그녀의 부상을 걱정했다. 하지만 오히려 그녀에게서 전투에 대한 전문 지식을 배우게 되었다. 그러나 로빈이 찾아오자, 디나는 무척 당황하고 말았다. 알고 보니 그녀가 다친 이유는 바로 로빈 때문이었던 것이다...",
  str_files_story_des_23101 = "당신은 로빈과 2미터의 거리를 두고 디나에게 어울리는 선물을 고르는 걸 도와주기로 했다. 하지만 선물을 고르는 로빈의 안목은 뭔가 상당히 기묘했다...",
  str_files_story_des_23201 = "최근 당신은 미아의 다른 인격인 「바바 야가」에게 계속해서 괴롭힘을 당했고, 이에 미아를 찾아가 물어보았지만, 알고 보니 「바바 야가」가 화를 내는 것은 당신이 건드려선 안 될 사람을 건드렸기 때문이라고 한다.",
  str_files_story_des_23301 = "쿠스쿠타는 최근 아침 일찍 나가서 저녁 늦게 들어온다. 그것이 신경 쓰인 당신이 쿠스쿠타에게 무슨 일이 생겼냐고 물어보니... 쿠스쿠타가 당신을 데리고 간 곳은... 「그녀」의 묘비 앞?!",
  str_files_story_des_23401 = "타키는 금색 샌드버그를 찾아달라는 이상한 의뢰를 받았다. 이에 당신과 타키는 세상에서 둘도 없는 특이한 샌드버그를 찾기 위해 함께 샌드버그의 고향인 레디젤 사막으로 향했다. 하지만 렉커가 값을 매길 수도 없는 그 금색 샌드버그를 금빛 샌드버그 단백질 파우더로 만들어버렸다!",
  str_files_story_des_23501 = "사람들의 호감 때문에 골치가 아픈 플뢰르는 또 고민에 빠져 있다. 어떻게 하면 그를 위로할 수 있을까?",
  str_files_story_des_23601 = "스모키에 대한 사람들의 인식은 매우 나쁜 듯하다. 이에 스모키의 이미지를 좋게 만들어 주기 위한 작전이 시작되었다...",
  str_files_story_des_23701 = "병 같지 않은 「병」에 걸린 조종사. 이에 그람은 치료를 위해 약 같지 않은 「약」을 사용했고. 효과는 굉장했다.",
  str_files_story_des_23801 = "콜로서스에 「콜로서스 최강자 도전」이라는 이상한 팻말이 나타났다. 대체 무슨 일일까...",
  str_files_story_des_23901 = "실수로 알루라가 아끼는 진귀한 소장품을 깨트리고 말았다. 하지만 그녀는 예상 밖의 반응을 보이는데...",
  str_files_story_des_24001 = "콜로서스에서 당신과 파로마는 한 책을 두고 이야기를 나누었고, 그녀는 당신에게 익숙하면서도 낯선 이야기를 들려주었다...",
  str_files_story_des_24101 = "나로세르는 콜로서스에 다양한 식물 화분을 가져왔다. 당신은 선인장 한 그루를 받아 방에 두었고, 며칠 후 이상한 일이 벌어졌다...",
  str_files_story_des_24201 = "트위티는 갑자기 당신에게 어떤 타입의 여자를 좋아하는지 물었다. 이 녀석은 대체 무슨 생각을 하는 걸까...",
  str_files_story_des_24301 = "당신은 우연히 베델의 취미에 대한 제인의 기록을 손에 넣게 되었다. 그리고 그녀는 다급하게 이 「증거」를 인멸하려는 것 같다...",
  str_files_story_des_24401 = "백화 용병단의 「거래의 날」을 보내고 나서... 루크에 대해 조금 더 이해하게 된 것 같다.",
  str_files_story_des_24501 = "피트만이 평소와 다르게 갑자기 선글라스를 끼고 나타나 당신에게 도움을 청했다... 대체 무슨 일일까.",
  str_files_story_des_24601 = "최근 오로리안들 사이에서 어떤 비밀 화집이 유행하고 있다고 한다. 그 화집에는 당신의 작품도 있다고 하는데... 화집의 제작자는 양복을 입은 그 두 사람인 것 같다...",
  str_files_story_des_24701 = "사실은 조무가 헤이디와 무슨 이야기를 하고 있는 건지 물어보고 싶었을 뿐이었는데, 갑자기 끌려가서 「두뇌 배틀」에 참가하게 되었다...",
  str_files_story_des_24801 = "일루미나의 치안관 커디는 예상외의 상황으로 인해 여러 업무를 빠트리고 말았다. 그녀를 조금 도와주는 건 어떨까.",
  str_files_story_des_24901 = "배고픔에 시달리던 당신은 로라가 만든 벌꿀 케이크를 보게 된다. 그러나 로라는 케이크를 먹기 전 반드시 어떤 일을 해야 한다고 하는데...",
  str_files_story_des_25001 = "콜로서스에 한 신비한 독심술의 대가가 나타났다고 한다. 그의 비밀은 대체 무엇일까...",
  str_files_story_des_25101 = "시오반 씨가 뭔가 숨기고 있는 것 같다. 가서 물어보자.",
  str_files_story_des_25201 = "요즘 에리카가 콜로서스에서 자꾸 이상한 소리가 들린다고 한다. 대체 무슨 일일까...",
  str_files_story_des_25301 = "루비의 가방에는 왜 다른 사람들의 물건이 잔뜩 있는 걸까? 루비 자신도 영문을 모르는 것 같다...",
  str_files_story_des_25401 = "플로리나가 다급하게 날 찾고 있다. 무슨 중요한 볼일이 있다고 한다.",
  str_files_story_des_25501 = "루즈가 부탁할 게 있으니 지금 바로 휴식실로 오라고 한다.",
  str_files_story_des_25601 = "신악의 방울이 울린 그 날, 뒤늦게 찾아온 린네는 당신에게 운도의 풍습을 가르쳐 주었다...",
  str_files_story_des_25701 = "카야노가 요즘 무척 수상쩍은 것이, 뭔가 고민이 있는 것 같다...",
  str_files_story_des_25801 = "아메모리가 휴식실에서 훈련을 하고 있는 것 같다. 가서 한번 구경해 볼까?",
  str_files_story_des_25901 = "요우가 당신에게 전에 사방을 누비며 의협을 실천했던 이야기를 해 주었다.",
  str_files_story_des_26001 = "모모와 안즈가 요리에 대한 일로 논의하고 싶은 게 있다고 한다.",
  str_files_story_des_26101 = "호넷과 실버의 안내를 받은 한 수수께끼의 생물이 콜로서스에 찾아왔다...",
  str_files_story_des_26201 = "아주르는 당신에게 드라이브를 하러 가자고 했지만, 차가 멈춘 곳은 파티가 열리고 있는 한 술집 밖이었다.",
  str_files_story_des_26301 = "로이가 「새로운 발명 실험을 위한 조교 모집」 의뢰를 걸었다. 보수는 꽤 많이 주는 것 같다.",
  str_files_story_des_26401 = "레노어는 천 인형을 만들기 위해 사방으로 재료를 찾고 있었다...",
  str_files_story_des_26501 = "조종사는 콜로서스에서 우연히 길스를 만났고, 길스가 만든 「이야기」 속에 휘말리고 말았다.",
  str_files_story_des_26601 = "메이는 단말기를 통해 이상한 메시지를 보냈다. 왠지 중요한 할 말이 있는 것 같다...",
  str_files_story_des_26701 = "라인하르트의 곁에서 그녀의 하루를 체험해 볼 수 있다고?! 하지만 이 여정은 예상과는 다른 방향으로 흘러가는 것 같다...",
  str_files_story_des_26801 = "새로운 힘을 받아들인 바이스는 자신이 감정을 잃었을까 두려워하기 시작했다. 그녀의 고민을 해결해주기 위해, 당신과 동료들은 「테스트」를 계획했다...",
  str_files_story_des_26901 = "헤븐즈 밸리에서 새로운 힘을 손에 넣은 바튼이 조금 이상해진 것 같다. 착각이었으면 좋겠는데...",
  str_files_story_des_27001 = "니나는 당신에게 직접 만든 「맛있는 요리」를 맛보게 했고, 그 요리에 담긴 이야기를 들려주었다.",
  str_files_story_des_27101 = "사나에는 「메이드 학원」의 졸업 시험을 보러 간다고 한다. 하지만 시험 참가 조건이 조금 이상한 것 같다...",
  str_files_story_des_27201 = "카렌은 까다로운「밀수 사건」을 해결했다. 과연 어떻게 된 일이었는지 그녀의 이야기를 들어보자.",
  str_files_story_des_27301 = "시엘은 진지하게 많은 계획을 세웠지만, 사실 그 모든 계획은 그저 강화복을 입고 당신과 함께 바다를 보고 싶었을 뿐이었다.",
  str_files_story_des_27401 = "피아 혼자 복도 한복판에서 화를 내고 있고, 키아로도 어디 갔는지 모르겠다. 대체 무슨 일일까?",
  str_files_story_des_27501 = "멜트, 사블리, 팜므 세 자매가 특별한 인터뷰를 시작했다... 제노는 뭐라고 대답했을까?",
  str_files_story_des_27601 = "레인보우의 부탁을 받고 서커스단 단원들을 야외 공연에 데려다주게 된 당신, 그러나 뜻밖에도 레인보우의 컨디션이 안 좋아지고 마는데...",
  str_files_story_des_27701 = "폴룩스가 움브라톤으로 쇼핑을 가자고 한다. 하지만 사실 그녀는 어떤 특별 작전을 계획한 것이었다.",
  str_files_story_des_27801 = "카스타가 카지노에 같이 가자고 한다. 「행운」의 가호를 받는 그녀는 과연 카지노에서 어떤 활약을 보여줄까? 정말 기대가 된다.",
  str_files_story_des_27901 = "당신의 부탁을 받은 이리돈은 하급 재판관의 사무실을 견학시켜 준다고 했다. 그러나 의외로 그는 졸고 있었고, 심지어 이상한 잠꼬대를 하고 있었다.",
  str_files_story_des_28001 = "뿌리를 찾는 여정은 창조에 대한 영감을 찾을 수 있다고 한다. 당신은 리리카를 데리고 그녀가 오랜 시간 떠나 있던 고향으로 돌아갔다...",
  str_files_story_des_28101 = "미노스가 안데르센 저택 근처에서 열리는 연회에 당신을 초대했다. 그곳에서 안도마 안데르센 백작이 중요한 발표를 한다는 모양이다.",
  str_files_story_des_28201 = "의적 정신을 탐구하는 새디는 당신에게 때맞춰 도움의 손길을 내밀었다. 그러나 새디가 걷는 탐구의 길은 그리 순탄하지 않았다. 혼란에 빠진 그녀는 과연 어떻게 이 상황을 타개할까?",
  str_files_story_des_28301 = "악셀리아는 「진다」는 게 어떤 느낌인지 궁금했다. 과연 그녀는 새로운 경험을 할 수 있을까?",
  str_files_story_des_28401 = "베르타가 백야성 의학원 대표로 움브라톤에서 의학 강연을 하게 되었다. 그런데 사람들이 그녀를 반기지 않는 듯한데...",
  str_files_story_des_28501 = "골디는 최근 보기 드물게 불면증에 시달리고 있다. 당신은 그녀를 괴롭히는 트라우마를 알게 된 뒤, 함께 문제를 해결하기로 결정했다.",
  str_files_story_des_28601 = "또 다른 환상동물 마스터로부터 도전을 받은 비크! 하지만 자신과는 아무런 상관도 없다는 태도를 보이고 있다. 정말 괜찮은 걸까?",
  str_files_story_des_28701 = "브랜디가 일자리를 잃지 않도록 동행 취재를 재차 수락했지만, 기록하는 타이밍이 뭔가 미묘하다...",
  str_files_story_des_28801 = "종서는 당신을 쌍사성 자택으로 초대했고, 당신은 신나서 출발 준비를 하고 있었다...",
  str_files_story_des_28901 = "당신과 목월백은 각자의 목적을 품고 쌍사성 상업 지역으로 향했지만, 그곳에서 한 「상인」에게 속고 만다...",
  str_files_story_des_29001 = "리청은 갑자기 닥친 「의료 분쟁」에 화가 났지만, 물론 그렇게 쉽게 포기할 리청이 아니다.",
  str_files_story_des_29101 = "바이스가 레디젤 렌치에 보낸 편지가 소식이 없다고 불평하고 있다. 아무래도 예리아에게 가서 물어봐야 할 것 같다...",
  str_files_story_des_29201 = "키아의 편지 가방이 무거운 것을 본 당신은 키아와 함께 편지를 배달하겠다고 나섰지만, 울고 있는 수신자를 만나게 되는데...",
  str_files_story_des_29301 = "티나가 자신이 꾼 꿈 이야기를 해 주겠다고 한다. 하지만 아무래도 단순한 꿈이 아닌 것 같은데...",
  str_files_story_des_29401 = "소녀의 마음을 가지고 있는 사람이라면 어느 정도는 멋진 기사가 공주를 구하는 로맨틱한 장면을 동경하기 마련이지만, 그런 환상은 레인에겐 해당 사항이 없다.",
  str_files_story_des_29501 = "당신과 마티외는 출소한 전직 범죄자들이 연 모임에 참석했다. 그러나 마티외가 막말을 퍼부어 모두의 화를 돋웠고, 당신은 철창 안에 갇혀 버리기까지 하는데...",
  str_files_story_des_29601 = "하티가 움브라톤에서 우연히 이상한 모녀를 만났다. 말을 하지 못하는 딸이 하티를 잘 따르자, 소녀의 어머니는 아예 딸을 하티에게 맡겨 버리는데...",
  str_files_story_des_29701 = "크리스틴에게 오페라 하우스의 티켓을 받은 당신은 백야성의 오페라 하우스에 공연을 보러 가기로 하는데...",
  str_files_story_des_35001 = "잉겔이 일루미나 전투 준비실에 참관을 오라며 당신을 초대했다. 아마 공유하고 싶은 새로운 무언가가 있는 것 같은데...",
  str_files_story_des_35002 = "언제나 물자 부족에 시달리는 강철가시 기사단을 위해, 레오는 어쩔 수 없이 기사단을 이끌고 어둠의 밑바닥으로 물자 수색을 떠났다. 그러나 어둠의 밑바닥으로 향하던 기사단은 도움이 필요한 민간인 피난민 무리와 마주치게 되고, 레오는 결단을 내린다...",
  str_files_story_des_35003 = "그날, 아나톨리가 찾아 와 당신이 휴식실에서 잃어버린 책을 찾게 해 주었다.",
  str_files_story_des_35004 = "솔라드는 먼 곳을 바라보며 왠지 어떤 추억에 젖어 든 것 같다...",
  str_files_story_des_35005 = "어설퍼도, 서툴러도 괜찮다. 그럼에도 누군가는 열심히 노력하는 진실된 당신을 아낄 테니까.",
  str_files_story_des_35006 = "쟈키니는 점으로 레디젤 사막에서 누군가가 도움이 필요하다는 것을 알게 되었다. 그러나 쟈키니의 점술은 그다지 신통치 않았고, 심지어 수정구슬까지 자주 잃어버리곤 했다. 과연 쟈키니는 무사히 임무를 완수할 수 있을까?",
  str_files_story_des_35007 = "여행은 사람들에게 새로운 경험을 가져다주지만, 한편으로는 낯선 사람에게서 익숙한 모습을 보여주기도 한다.",
  str_files_story_des_35008 = "파이어플라이는 블랑의 근무복 세탁을 도와주었지만, 그녀의 드레스에 생긴 얼룩은 아무리 씻어도 지워지지 않았다. 대체 어떻게 된 일일까.",
  str_files_story_des_35009 = "당신은 우연히 콜로서스의 카페에서 요리를 맛보고 있던 세나를 만났고, 미식과 여러 화제에 대해 이야기를 나눴다.",
  str_files_story_des_35010 = "보프가 「좋은 걸」 나눠 주겠다며 데누오 계곡에서 만나자고 한다. 대체 뭘 주려는 걸까?",
  str_files_story_des_35011 = "항상 웃음기 가득하던 로렐라이가 요즘 부쩍 한숨을 쉬곤 한다. 무슨 고민이라도 있는 걸까?",
  str_files_story_des_35012 = "콜로서스의 방 안에서 당신은 언젠가 본 듯한 기분이 드는 빈 종이를 발견했다. 좋지 않은 기억이 떠오르고, 종이의 뒷면을 확인할 새도 없이 당신은 언제 눈앞에 나타날지 모르는 상대를 찾아 다니기 시작한다. 그렇지만 뜻밖에도 예상했던 상황은 전혀 발생하질 않는데....",
  str_files_story_des_35013 = "맑고 여유로운 어느 하루, 당신은 조셀린에게서 「약속」 때문에 평소보다 일찍 하루 일과 준비를 마쳐야 하니 도와달라는 메시지를 받는다.\n바쁜 아침 일정을 마무리한 후, 조셀린은 당신에게 약속 장소로 함께 가자고 부탁하는데...",
  str_files_story_des_35014 = "지식욕이 왕성한 안토니가 파이어플라이에 숨겨져 있는 비밀을 밝히려 파이어플라이를 연구하려 한다.",
  str_files_story_des_35015 = "얼마 전부터 자리야가 바이스에게 더 정확하게 조준하는 법을 배우고 있다. 과연 자리야의 루미나틱스 제어 실력은 얼마나 늘었을까?",
  str_files_story_des_35016 = "아직 평범한 오로리안을 대하는 게 낯설기만 한 33호가 새 친구를 사귀려고 한다. 어서 도움을 줘야 한다.",
  str_files_story_des_35017 = "파프닐은 하루 종일 게임을 하는 것 같다. 신경이 쓰이니 역시 파프닐을 만나러 가 보자.",
  str_files_story_des_35018 = "칸나가 자기의 그림일기를 보여줬다. 열심히 적었다는 것을 알 수 있는 일기였다!",
  str_files_story_des_35019 = "다시 한번 이 세계에 찾아온 토르가 당신을 위해 특별한 요리를 준비하고 있다.",
  str_files_story_des_35020 = "엘마가 갑자기 스카이워커호에서 일자리를 찾고 싶다고 한다. 대체 무슨 일이 생긴 걸까?",
  str_files_story_des_35021 = "건강한 생활 습관은 무척 중요하다. 밤샘은 절대 금물!",
  str_files_story_des_35022 = "레베카가 다른 사람이 자기 방에 들어오는 걸 한사코 거부하고 있다. 아무래도 방 안에 다른 사람에게 들키고 싶지 않은 비밀이 숨겨져 있는 모양인데...",
  str_files_story_des_35023 = "레베카가 진료소 일로 계속 바쁘다는 사실을 알게 된 이사가 당신에게 레베카를 마음 놓고 푹 쉴 수 있는 곳에 데려가 달라며 상담해 왔다. 하지만 언니로서의 걱정이 조금은 과한 듯싶은데...",
  str_files_story_des_35024 = "선극은 일전에 조종사에게 받은 도움에 감사하기 위해 식사를 대접하기로 했다. 마침 기관술에 대해 조종사도 많은 흥미가 있었고, 두 사람은 식사를 하며 이야기를 나누기 시작했다.",
  str_files_story_des_35025 = "이스타반이 비밀리에 당신에게 메시지를 보냈다. 왠지 주변 사람들에게는 말할 수 없는 일이 생긴 듯하다.",
  str_files_story_des_35026 = "버질은 움브라톤의 골동품 시장에 가고 싶지만, 왠지 혼자서는 갈 엄두가 나지 않는 듯하다...",
  str_files_story_des_35027 = "그 위풍당당한 공중상회의 회장에게도 회수할 수 없는 「부실채권」이 있을 줄은 몰랐다.",
  str_files_story_des_35028 = "시대를 바꾸는 발명품을 완성하기 위해, 알골은 당신에게 실험에 협력해 달라고 부탁했다...",
  str_files_story_des_35029 = "진예는 아스트라 대륙의 새로운 것들을 보고 싶다고 한다. 이에 당신은 그녀를 데리고 움브라톤으로 향하는데...",
  str_files_story_des_35030 = "나송은 아스트라에서 처음으로 퇴마 의뢰를 받았다. 과연 무엇을 만나게 될까...",
  str_files_story_des_35031 = "눈소나무 숲에 위기가 다가오자, 티아라는 PlayerName에게 도움을 요청하고, 두 사람은 힘을 합쳐 함정을 설치하는데…",
  str_files_story_des_35032 = "레이첼은 최근 식사 대신 영양제를 복용하고 있고, 이 사실을 알게 된 아이테르는 충격에 빠졌다...",
  str_files_story_des_35033 = "제타는 최근 무언가를 시도하려고 안달이 난 듯한 모습이다. 대체 무엇을 계획하고 있는 것일까.",
  str_files_story_des_30001 = "파산을 앞두고 있는 콜로서스. 바이스는 자신이 「가장 잘하는 일」... 요리를 다시 탐구하기 시작했다. 과연 이번 요리는 어떤 맛일까...",
  str_files_story_des_30002 = "이제 카렌은 미지에 대해 두려움을 버리고, 바다의 아름다움을 직접 보게 될 것이다. 당신이 그녀의 손을 잡아 준다면 말이다.",
  str_files_story_des_30003 = "신기루가 만들어 내는 환영은 속에는 복잡한 진심이 담겨 있는 법. 허구의 이야기 속에도 그의 진실이 반영되어 있다.",
  str_files_story_des_30004 = "가치가 있는 상품으로 꼭 즐거움을 살 수 있는 것은 아니다. 그러나 값을 매길 수 없는 선물은 모든 고민을 씻어낼 수 있다.",
  str_files_story_des_30005 = "바람 소리, 새의 울음소리, 파도의 소리... 소라 속에 담긴 여름날 해변의 낭만적인 소리들. 그리고 당신을 향한 감사를 담은 말소리.",
  str_files_story_des_30006 = "바튼은 일루미나 해군 부대의 창설을 위해 험난한 여정을 시작했다...",
  str_files_story_des_30007 = "시로나는 매년 이 시기가 되면 특별한 옷을 입고 아무도 모르는 어떤 장소에 다녀온다고 한다. 그리고 이번엔 그 비밀에 대해 파악할 수 있는 기회가 찾아왔다.",
  str_files_story_des_30008 = "히이로는 오래된 사진 한 장을 바라보며 생각에 잠겨 있다. 사진 속에는 그녀의 예전 모습이 담겨 있었다. 어떻게 하면 그 추억을 지켜줄 수 있을까.",
  str_files_story_des_30009 = "바이스는 당신의 개인 물품을 발견했다... 그것은 극동의 추억이 담긴 물건이었다. 선향불꽃에 불을 붙인 그녀는 평소와 무엇이 다른 걸까.",
  str_files_story_des_30010 = "당신은 움브라톤의 거리에서 제인과 마주쳤고, 근처의 고아원에서는 비명 소리가 들려왔다... 대체 무슨 일이 벌어진 걸까?",
  str_files_story_des_30011 = "필리시는 화가 났다! 당신과 바이스는 서로를 바라보았지만, 사건의 범인은 아무것도 모른다는 듯 바닥에 주저앉아 발을 핥으며 귀엽게 야옹~하고 울 뿐이었다.",
  str_files_story_des_30012 = "비가 오는 날씨는 새가 날아가기에 적합하지 않다. 하지만 상처 입은 새는 여전히 날갯짓을 하고 있다. 녀석이 날아가는 방향은 테사의 마음의 향하는 곳일지도 모른다...",
  str_files_story_des_30013 = "미자드는 그녀의 모든 것을 일과 연구에 바친다. 쉬는 시간도 예외는 아니다...",
  str_files_story_des_30014 = "펙트는 어디서 구한 건지 빅토리아와 비슷한 복장을 가져왔다. 그녀는 이 옷으로 대체 뭘 하려는 걸까.",
  str_files_story_des_30015 = "갑작스럽게 카론의 「공연 초대장」을 받게 되었다! 당신은 복잡한 심경과 함께 약속 장소로 향했다...",
  str_files_story_des_30016 = "이별의 시간, 예정된 것이기라도 한 듯 비가 내렸다. 다음 여름에도 이 모습을 볼 수 있을까?",
  str_files_story_des_30017 = "아이리나는 신기한 마법의 드레스를 얻게 되었다. 하지만 밤 12시가 되면 드레스가 무언가로 변한다고 하는데...?",
  str_files_story_des_30018 = "당신은 새해에 기괴한 선물을 받게 되었다. 거대한 선물상자는 계속해서 흔들리며, 기묘한 기침 소리를 내고 있었다...",
  str_files_story_des_30019 = "거울 호수 근처에서 당신은 연회에서 혼자 빠져나온 나시리스를 발견했다. 그녀는 호수면을 바라보며 무언가 생각에 잠긴 듯했다.",
  str_files_story_des_30020 = "빅토리아는 기묘한 거울을 하나 가지고 있었다. 당신이 그 거울 앞에 다가갔을 때, 그 안에 비친 것은 당신의 모습이 아니었다.",
  str_files_story_des_30021 = "루이스와 노아는 당신을 데리고 북방의 어떤 골목을 지켰고, 이는 전설 속 결코 멈추지 않는 마차를 보기 위해서였다...",
  str_files_story_des_30022 = "걱정과 근심은 결코 떨쳐낼 수 없는 것이 아니다. 가끔은 세 잔의 음료와 좋은 카페만 있으면 해결할 수 있다.",
  str_files_story_des_30023 = "새 옷으로 갈아입은 나딘, 그녀는 콜로서스에서의 일을 업무라고 생각해 진지하게 임하려 하지만, 사실 당신은 그녀가 조금이라도 더 쉴 수 있게 해주고 싶었을 뿐이다.",
  str_files_story_des_30024 = "지식을 얻기 위해 과외 수업을 구매한 당신, 하지만 찾아온 선생님은 뜻밖에도... 샤리였다.",
  str_files_story_des_30025 = "석양 아래, 우리엘은 당신과 함께 일련의 「문학적 교류」를 진행했다... 왠지 우리엘에 대한 이해가 더 깊어진 것 같은 느낌이다.",
  str_files_story_des_30026 = "밝은 햇살 속에서 마지는 자전거를 타고 맑은 하늘을 가로질렀고, 온 힘을 다해 불쌍한 톱날 리크를 쳐서 날려버렸다...",
  str_files_story_des_30027 = "갑자기 어디서 구한 건지 알 수 없는 이상한 옷을 입은 이브, 그 옷을 입고 레디젤 렌치의 인기 콘테스트에서 모두를 응원하겠다고 하는데...",
  str_files_story_des_30028 = "처음으로 보게 된 카렌의 표정... 그것은 놀람, 불안, 분노, 그리고 어쩔 줄 모르는 수줍음과 귀여운 부끄러움이었다.",
  str_files_story_des_30029 = "레이스는 갑자기 당신에게 강부성으로 나들이를 가자고 했다. 설마... 이것이 바로 말로만 듣던 데이트 신청?",
  str_files_story_des_30030 = "간만에 찾아온 휴일, 트위티는 모두에게 깃털공 놀이를 하자고 했다. 지는 사람은 반드시 벌칙을 받아야 한다고 하는데...",
  str_files_story_des_30031 = "벚꽃의 향기, 과연 누가 그 매력에 빠지지 않을 수 있을까?",
  str_files_story_des_30032 = "동방의 무사 아카나미 사메노스케는 누이인 이브의 편안한 여생을 위해 악을 멸하는 길에 나섰다....」 이게 바로 요즘 극동에서 유행하는 소설인가?",
  str_files_story_des_30033 = "강부성 역에서 우연히 이리돈을 만난 당신, 하지만 그녀는 당신을 용의자처럼 심문하기 시작하는데...",
  str_files_story_des_30034 = "찬드라의 심리 상담은 정말 신기하다... 오랫동안 쌓였던 감정을 해방시키는 건 대체 어떤 느낌일까?",
  str_files_story_des_30035 = "베델은 이스타반에게 대체 어떤 옷을 골라준 것일까... 그 모습이 정말 궁금하다.",
  str_files_story_des_30036 = "코놀리는 자동차 경주의 치어리더를 맡아 달라는 부탁에 동의했지만, 차마 첫발을 내딛지 못하고 있었다.",
  str_files_story_des_30037 = "한 인형 파는 소녀가 「마룡의 심판」에 대한 신기한 이야기를 들려 주었다... 잠깐만, 이 이야기 속 심판이란 사람, 설마...?",
  str_files_story_des_30038 = "폭염의 날씨, 작열하는 커브, 스릴 넘치는 레이스... 과연 타키는 이 레이스에서 몇 등을 할 수 있을까?",
  str_files_story_des_30039 = "당신은 라파엘의 초대로 저택에 방문했다. 그러나 그 저택의 손님 접대 방식은 꽤 독특했다...",
  str_files_story_des_30040 = "그녀의 심장이 이토록 뛰는 것은 처음이었다.",
  str_files_story_des_30041 = "루이스가 당신에게 「소꿉놀이」를 하자고 했다. 과연 당신은 어떤 역할을 맡게 될까?",
  str_files_story_des_30042 = "앨리스의 케이크가 도둑맞았다고? 잔뜩 화가 난 앨리스는 직접 도둑에게 벌을 내리기로 결심했다!",
  str_files_story_des_30043 = "플뢰르가 빵을 만들 만한 곳을 찾고 있다... 이상하다. 설마 업종을 바꾸려는 걸까?",
  str_files_story_des_30044 = "렉커는 「어떤 물건」을 찾기 위해 새로운 옷으로 갈아입었다. 이 옷은 렉커가 더 빠르게 움직이도록 만들어 준다고 한다.",
  str_files_story_des_30045 = "당신은 레오나와 함께 해변에서 시간을 보냈지만... 그녀가 가장 보고 싶지 않은 「그 사람」과 마주치게 될 줄은 몰랐다.",
  str_files_story_des_30046 = "스모키는 깊은 밤의 신비한 괴도로 변했고, 값을 매길 수조차 없는 보석을 훔쳐 가 버렸다... 하지만 사라진 것은 단지 그 보석만은 아닌 듯하다.",
  str_files_story_des_30047 = "그로누가 새 게임을 개발했다. 만약 당신이 클리어하지 못하면 거액의 콜로서스 수리비를 청구하겠다고 하는데...",
  str_files_story_des_30048 = "풀려난 안개나비는 눈 깜짝할 사이에 사라지는 환상이 되었다. 하지만 루크는 이 아름다운 광경을 영원히 간직할 방법을 가지고 있었다.",
  str_files_story_des_30049 = "새로운 옷차림으로 파도와 함께 백사장에 등장한 베벌리, 전설의 서막이 오른다.",
  str_files_story_des_30050 = "Ms. 블랑을 돕기 위해 그녀의 임시 매니저를 맡게 된 당신, 하지만 매니저 일이 쉽지만은 않다.",
  str_files_story_des_30051 = "의뢰를 받은 당신은 100상자의 술을 어떤 곳으로 배달하게 되었다. 하지만 그 의뢰인은 바로...",
  str_files_story_des_30052 = "당신은 움브라톤에서 신문을 팔려고 하는 웬디를 만났다. 사업을 확장하려는 걸까?",
  str_files_story_des_30053 = "스칼렛은 「무덤」을 충실히 지키고 있을 뿐만 아니라, 「무덤」에 속한 망자들의 모든 목소리에 귀를 기울인다.",
  str_files_story_des_30054 = "헤이디는 자난성의 초대를 받아 「일일 치안관」 임무를 맡았지만, 그녀의 임무는 시작부터 난관에 부딪히게 되었다...",
  str_files_story_des_30055 = "전설의 핫소스를 얻기 위해 레비는 스파이가 되어 움브라톤의 감옥에 잠입했다. 그러나 사건은 그녀의 예상과 반대로 흘러갔다...",
  str_files_story_des_30056 = "조종사는 한 비밀 의뢰를 맡아 유명 배우를 인터뷰하게 되었다...",
  str_files_story_des_30057 = "블랙 로즈 클랜의 리더인 파로마는 당신을 조수로 임명했고, 그녀의 이번 복수 대상은 백야성의 귀족이었다. 마침 그 심판관도 이를 쫓고 있었는데...",
  str_files_story_des_30058 = "쉬는 날, 당신은 베들레헴 폐하와 함께 책을 읽던 중, 우연히 오래전 쓰인 샤야의 환상이 담긴 노트를 발견하게 되는데...",
  str_files_story_des_30059 = "북방으로 초대된 조종사, 새해를 앞둔 어느 날 새벽, 잠에서 깬 조종사의 귓가에는 윈터 팰리스에서 울려 퍼지는 노비오의 피아노 연주가 들렸다...",
  str_files_story_des_30060 = "자난성에는 「정의 집행 a.k.a. 저지먼트」에 관한 전설이 퍼지기 시작했다. 누군가 규율을 어길 때마다 고막을 찢을 듯한 거대한 천둥소리가 들린다고 한다...",
  str_files_story_des_30061 = "리리암은 저마다 다른 성격을 지녔지만, 「최고의 사명」이라는 공동의 목표를 위해 모든 것을 바치려 한다.",
  str_files_story_des_30062 = "과학 연구에 매달리던 시오반이 그로누와의 게임 대결을 피하기 위해 뜻밖에도 콘서트 오디션에 참가하기로 했다...",
  str_files_story_des_30063 = "해마다 열리는 관월제가 다시 찾아왔다. 연인들의 순수한 사랑을 지키기 위해, 한 갈래의 번개가 거리와 골목을 누빈다...",
  str_files_story_des_30064 = "피트만과 백야성의 성문 앞에서 만나기로 약속한 당신은 약속 장소에 도착하는데...",
  str_files_story_des_30065 = "크로이는 귀족의 결혼식에 연주자로 초대됐다. 그녀가 만든 음악은 신부의 마음을 감동시켰지만, 그로 인해 예상치 못한 사건이 발생하고 만다... 신부가 도망쳤다!",
  str_files_story_des_30066 = "당신은 움브라톤에서 길을 걷던 중 갑자기 나타난 낯선 남자들에게 붙잡혀 지하 살롱으로 끌려가 버렸다. 그리고 그곳에서 뜻밖에도 제노를 만나게 되는데...",
  str_files_story_des_30067 = "훌륭한 사냥꾼은 위장에 능숙한 법, 사냥감이 경계심을 내려놓게 만들어야 사냥감을 옴짝달싹 못 하게 몰아넣을 수 있다.",
  str_files_story_des_30068 = "당신은 움브라톤에 갔다가 피아, 비크, 시라 세 사람을 만났다. 세 사람은 한데 모여 뭔가를 논의하는 중인 것 같은데...",
  str_files_story_des_30069 = "당신은 길을 걷다 디나의 모습을 보았다. 그 참에 디나에게 인사를 하려 했지만...",
  str_files_story_des_30070 = "페기와 쿠마가 당신을 찾아와서는 간단한 의뢰를 맡기고 싶다고 했다. 그러나 그 의뢰 때문에 전혀 예상치도 못하게 도망자 신세가 돼 버리고 마는데...",
  str_files_story_des_30071 = "당신은 여행 도중 한 마을에 들린 김에 몇 가지 물건을 사려고 했지만, 마을 전체가 당신을 향해 이빨을 드러냈다. 광기에 휩싸인 마을 사람들에게 목숨을 위협받으며 쫓기고 있을 때, 당신은 엘시와 마주쳤다...",
  str_files_story_des_30072 = "쿠스쿠타와 함께 움브라톤에서 연쇄살인 사건을 조사하게 된 당신, 소름 끼치는 범인과 겁에 질린 생존자들, 그리고 위기의 상황에서 쿠스쿠타는 빛나는 인성을 보여 주었다...",
  str_files_story_des_30073 = "움브라톤의 고아원을 방문하려는 가브리엘이 당신에게 동행을 권했고, 두 사람은 함께 움브라톤으로 향했다.",
  str_files_story_des_30074 = "키팅은 우연히 금지된 흑마법서 한 권을 손에 넣었다. 그 금서의 마지막 페이지에는 무시무시한 마물을 연성하는 법이 적혀 있었고, 키팅은 고생 끝에 재료를 모아 연성을 시작했다.",
  str_files_story_des_30075 = "리아의 스터디 모임을 응원하기 위해 실바는 특별한 옷까지 차려 입었지만, 그 옷차림은 뜻밖에도 역효과를 내고 말았다.",
  str_files_story_des_30076 = "최근 운도에서 기괴한 유령 사건이 발생해 사람들을 두렵게 만들었다. 린네가 조사해 본 결과, 사건은 모두 검은 고양이 한 마리의 소행이었는데...",
  str_files_story_des_30077 = "사악한 마음을 품은 신도들에 의해 작은 가시나무는 성물로 받들어져 제물로 바쳐지지만, 그들에게 내려진 것은 은혜가 아닌 신의 철퇴였다.",
  str_files_story_des_30078 = "당신은 플로리나로부터 이단심문조의 비밀 임무를 완수할 수 있도록 함께 바다에 가 달라는 부탁을 받게 되는데...",
  str_files_story_des_30079 = "나로세르는 비치 선베드에 누워 느긋하게 바닷바람을 즐기며, 마침내 일에서 해방되어 해변의 도시에서 잠시나마 평온한 시간을 보낼 수 있었다.",
  str_files_story_des_30080 = "미제니는 한 모래고양이를 사막에 있는 원래 집으로 데려다주려고 한다. 하지만 레디젤 사막에 도착하고 나서야 그게 생각보다 쉬운 일이 아니라는 사실을 깨닫게 되는데...",
  str_files_story_des_40101 = "당신과 카렌은 분주하고 번화한 항구 도시인 쌍사성으로 향했고, 그곳에서 두 사람은 뜻밖의 불청객과 마주치게 되는데...",
  str_files_story_des_40102 = "바이스에게 말하지 않고 쌍사성으로 아르바이트를 하러 간 당신은 그곳에서 무척 낯익은 사람을 만나게 되었다.",
  str_files_story_des_40103 = "동방풍의 복장을 입게 된 파티와 파시, 그 복장은 두 사람에게 생각지도 못한 능력을 주게 되는데...",
  str_files_story_des_40104 = "당신은 이브와 약속을 잡고 나들이를 가게 되었고, 들판에는 수많은 민들레가 피어 있었다. 이브는 잠시 생각에 잠긴 후, 자신의 소망을 담아 바람에 민들레 홀씨를 날려 보냈다.",
  str_files_story_des_40105 = "이리돈은 감히 마주할 수 없는 누군가를 만나기 위해 당신에게 동행을 부탁했다. 대체 어떤 사람이길래 대심판관조차 이토록 두려워하는 것일까.",
  str_files_story_des_40107 = "소설 출간 축하 연회를 마치고 아이리나는 당신에게 함께 해변을 산책하자며 약속했다. 따뜻한 햇살 아래, 그녀는 왠지 속마음을 털어놓고 싶은 듯했다...",
  str_files_story_des_30081 = "베들레헴 여왕이 해변에서 열리는 외교 활동에 참석한다. 하지만 드래곤 두 마리의 등장으로 상황이 소란스러워지는데...",
  str_files_story_des_30082 = "당신은 비크와 바다에서 금화를 찾기로 했다. 과연 이 신비로움이 가득한 바다에서 마음속으로 간절히 바라던 금화를 찾을 수 있을까.",
  str_files_story_des_30083 = "기묘한 종소리가 4호 박물관 내부에서 울려 퍼진다. 밤이 깊었다면 절대로 이 박물관에 발을 들여선 안 된다. 만약 발을 들인다면...",
  str_files_story_des_30084 = "북방 근처에 특이한 암귀 하나가 나타났고, 콘스탄틴은 PlayerName에게 동행인이 되어달라고 부탁했다.",
  str_files_story_des_30085 = "자리야는 한때 약속 장소였던 해변에 도착했지만, 만나기로 약속했던 사람은 이제 더는 그녀를 기다릴 수 없게 된 뒤였다...",
  str_files_story_des_30086 = "니나는 제5회 보석 대회의 참가를 준비하고 있었다. 우승을 차지하기 위해 그녀는 심지어 보석을 직접 착용하고, 사진 촬영도 했다. 그러나 찍힌 사진은 니나를 그다지 만족시키지 못했다.",
  str_files_story_des_30087 = "자신의 꿈을 이야기한 후 코놀리는 PlayerName에게 이끌려 스튜디오로 향했다. 이곳에서 그녀는 자신의 꿈을 이어갈 수 있을까.",
  str_files_story_des_30088 = "카프카와 PlayerName 두 사람은 체력 단련을 위해 사막 경주장으로 향했고, 이곳에서 카프카가 소개하려는 친구는...",
  str_files_story_des_30089 = "레비는 이상한 편지를 받았다. 「약한 사람들을 지켜주고 싶어? 그럼 일루미나 연구실로 와!」",
  str_files_story_des_30090 = "그람은 당신을 데리고 먼 길을 지나 아름답고 조용한 계곡으로 향했다. 설마 그는 그저 휴식을 취하고 싶었던 걸까?",
  str_files_story_des_30091 = "무너진 얼음동굴에 홀로 갇힌 시엘, 과연 이번에는 위험에서 벗어날 수 있을까.",
  str_files_story_des_30092 = "조종사는 단당과 만나 함께 달을 감상했고, 즐겁게 이야기를 나누던 중 잠든 조종사는 꿈에서 단당의 어린 시절 모습을 보게 되는데...",
  str_files_story_des_30093 = "나딘은 쌍사성에서 아르바이트를 시작했고, 매일 밤 등불을 들고 해안을 순찰했다. 그리고 그녀는 바다로 향하는 조종사와 마주쳤다.",
  str_files_story_des_30094 = "이천간은 낚시를 하던 당신에게 어떻게든 점괘 풀이를 듣게 하려고 자신이 용궁에서 겪은 일을 이야기하기 시작했다...이천간",
  str_files_story_des_30095 = "샤리가 비대칭인 옷을 입다니?! 하지만 그녀에겐 그래야만 하는 이유가 있었다고 하는데...",
  str_files_story_des_30096 = "리리카는 한 사회공헌 목적의 공연 요청을 받게 되었고, 그녀는 지금 도움과 격려가 필요했다...",
  str_files_story_des_30097 = "폴룩스는 당분간 떠나 있게 되었다고 한다. 그리고 그 이유는...",
  str_files_story_des_30098 = "히이로는 운앵 여관 할머니의 편지를 받았다. 아무래도 최근 운산의 「봉인」에 약간의 변화가 발생한 것 같다...",
  str_files_story_des_30099 = "집집마다 가족들이 다시 모이는 명절, 파솔로는 홀로 창가에 앉아 종이나비를 잘라 자신의 곁에 두었다...",
  str_files_story_des_30100 = "쌍사성에서 우연히 마주친 파우스트, 그는 낡은 고서를 잔뜩 샀고, 왠지 용주의 고대 문화를 연구하고 있는 듯했다.",
  str_files_story_des_30101 = "선극이 갑자기 찾아와 콜로서스를 빌려달라고 한다. 만 리 너머의 별하늘을 보고 싶어서라고 하는데...",
  str_files_story_des_30102 = "아드라스는 한때 밝은 미래를 상상했지만, 지금은 모든 것을 잊어버렸다. 그는 당신이 만들어 준 갑옷을 기회로 삼아 잠시나마 꿈의 단편을 회상했다.",
  str_files_story_des_30103 = "전쟁에서 부상을 입고 병상에 누운 악셀리아는 침대 옆 장미를 바라보며 비관에 빠졌다. 이때 조종사는 그녀에게 장미의 의미를 설명해 주었다...",
  str_files_story_des_30104 = "플라티나 선라이즈 호텔의 비수기, 플뢰르는 사장님의 요청에 따라 시설 유지보수 작업에 나섰고, 조종사를 「가족」으로 초대했다...",
  str_files_story_des_30105 = "자신의 우울한 오로리안의 삶을 이어가고 싶지 않았던 우리엘은 금서에 기록된 마법약을 마셨다. 그리고 조종사의 앞에 나타난 것은…",
  str_files_story_des_30106 = "의뢰를 받고 책을 전달하기 위해 로빈의 집으로 향한 PlayerName, 그곳에서 두 사람은 나른한 오후를 보냈다...",
  str_files_story_des_30107 = "시로나의 부탁을 받고 용 조각상의 잔해가 있는 유적에 온 PlayerName, 그곳에서 기다리고 있는 것은 드레스를 입은 시로나였다...",
  str_files_story_des_30108 = "장난을 쳐서 문제를 일으킨 안시아는 처벌로 의장대에 들어가 예절 훈련을 받게 되었다. 그녀는 이 난관을 극복하기 위해 PlayerName의 도움이 필요하다고 한다...",
  str_files_story_des_30110 = "골디의 아이돌 일과가 끝난 후, 「일일 매니저」가 된 당신은 골디와 함께 두 사람만의 시간을 시작했다...",
  str_files_story_des_30111 = "펙트는 움브라톤으로 식재료를 사러 가는 길에 동행해 달라고 당신에게 요청했다. 그러나 사실 그녀의 진짜 목적은...",
  str_files_story_des_30112 = "티나는 당신과 복슬이를 피크닉에 초대했고, 특별히 새 옷도 만들었다. 그러나 어렵게 계획한 나들이는 그리 순조롭지 않았다...",
  str_files_story_des_30113 = "오늘 레디젤 렌치에서는 봄버 존이 식당 일을 맡게 되었다. 요리에 대해 아무것도 모르는 그녀는 당신에게 감응 능력으로 식재료와 대화해 달라는 부탁을 하는데...",
  str_files_story_des_30114 = "교활한 밀렵꾼을 체포하기 위해 휴라드는 홀로 작전에 나섰고, 당신에 대한 신뢰를 바탕으로 지원군이 오길 기다렸다.",
  str_files_story_des_30115 = "목월백은 최고의 우렁쌀국수를 만들고 싶어 했고, 이를 위해서는 먼저 자신의 손으로 직접 우렁이를 잡아야만 했다...",
  str_files_story_des_30116 = "용주에 오색절이 찾아오자, 진예는 「막연한 소원」을 찾고 싶다며 당신을 데리고 시끌벅적한 거리를 구경하기 시작했다...",
  str_files_story_des_30117 = "레디젤 사막에서 일을 마친 당신은 이곳에 발이 묶인 잉겔을 만났다. 그녀는 자신이 길을 잃은 것이 아니라고 고집스럽게 주장하는데...",
  str_files_story_des_30118 = "한 유명 인사들의 연회에서 당신은 자신의 아이테르 신분 때문에 소란을 겪었다. 그 순간 갑자기 나타나 당신의 곤란함을 해소해 준 것은...",
  str_files_story_des_30119 = "바바라는 새로운 콘서트 무대를 선택했지만, 레디젤 아이돌의 스타일이 이곳에서 벽에 부딪혔다. 과연 당신은 그녀가 공연장을 만석으로 채울 수 있도록 도와줄 수 있을 것인가...",
  str_files_story_des_30120 = "상냥한 웨이터 라비는 당신에게 매장의 음식을 맛보라고 권유했다. 그러나 모두에게 맛있는 음식과 미소를 가져다주기 전, 그녀가 당신에게 가져다 준 것은...",
  str_files_story_des_30121 = "몰아치는 바닷물 아래, 예리아의 얇은 수영복은 보일듯 말듯 아슬아슬했다. 당신은 그녀를 위해 이 해변을 지켜줄 수 있을까...",
  str_files_story_des_40001 = "단당은 《대조서역기》라는 소설을 읽고 있었다. 비록 내용은 무척 이상했지만, 단당은 그 내용이 싫지만은 않아 보였다.",
  str_files_story_des_40002 = "이천간의 구관조 「다어」가 사라졌다고 한다. 이천간이 가지고 다니는 《연천통신권》에서 뭔가 단서를 찾을 수 있...을까?",
  str_files_story_des_35034 = "게임에서는 왠지 박쥐 아인을 빌런으로 설정할 때가 많은 모양이다. 그래서 바티아는 무척 슬퍼하고 있다. 하지만 다행히 우리에겐 「슈퍼 배트」가 있다.",
  str_files_story_des_30122 = "수년 동안 혼수상태에 빠져 있던 바튼의 상관 팡고가 깨어났다. 바튼은 서둘러 당신을 불렀고, 상관과 과거를 회상하기 시작했다...",
  str_files_story_des_35035 = "귀족들의 연쇄 죽음이라는 미스터리한 사건은 진리의 결사의 가장 참혹하고 어두운 면을 드러냈다...",
  str_files_story_des_35036 = "빌헬름은 당신을 데리고 보물찾기에 나섰고, 100년 전에 묻힌 오래된 물건을 찾아냈다...",
  str_files_story_des_35037 = "나일즈는 자신의 옛 은인을 걱정하며, 그녀가 안전한지 확인하고 싶어 했다.",
  str_files_story_des_35038 = "라이자는 당신을 위해 가장 강력한 무기를 만들어 주려고 했다. 하지만 문제에 부딪히게 되는데...",
  str_files_story_des_35039 = "「인맥과 정보는 상인의 생명이야」, 클라우디아는 말했다. 그리고 그 말대로 실천했다.",
  str_files_story_des_35040 = "파트리샤는 매우 「자극적」이라는 책을 손에 넣었다. 그 책의 내용은 무려...",
  str_files_story_des_30123 = "유라는 암초 위에 누워 있었고, 바다에는 흰 장미 꽃잎이 흩날리고 있었다. 당신은 유라 때문에 들어온 민원을 처리하러 왔지만, 그의 철학적 토론에 휘말리게 되는데...",
  str_files_story_des_30124 = "마티외는 원래 해변에서 조용한 휴가를 보내고 싶었지만, 「안 좋은 타이밍」에 당신이 그의 눈앞에 나타났다. 과연 무슨 일이 벌어지게 될까...",
  str_files_story_des_30125 = "당신은 스칼렛에게 모두와 함께 여름을 즐기자고 권했지만, 어쩌다 보니 그녀의 파리아 때문에 무덤으로 끌려들어가고 말았다. 그리고 그녀는 그곳에서 당신을 기다리고 있었다...",
  str_files_story_des_30126 = "라이자는 플라티나 선라이즈 호텔에서 친구들과 함께 아스트라에서의 마지막 여름 축제를 보낼 예정이다.",
  str_files_story_des_30127 = "대원수로부터 특별 휴가를 받았음에도 불구하고, 레이첼은 해변에서 여전히 워커홀릭의 면모를 보여주었다. 과연 어떻게 하면 그녀가 해변의 휴가를 즐기게 만들 수 있을까...",
  str_files_story_des_35041 = "마야는 왠지 당신에게 부탁할 일이 있는 모양이다. 그러나 약속 장소에 도착하자, 역시나 마야는 그 일을 깨끗이 잊어버린 뒤였다.",
  str_files_story_des_30131 = "당신은 물건을 사러 움브라톤으로 향했으나 가게는 문을 닫았고, 에이스 집사 미노스는 당신을 새로운 가게로 안내하며 자신의 과거에 대해 이야기하는데...",
  str_files_story_des_30128 = "낯선 천장, 낯선 병상, 그리고 당신을 보살피는 와타리... 과연 당신은 그가 특별히 준비한 「영양제」를 마실 것인가.",
  str_files_story_des_30130 = "안개가 자욱한 호화 스파에서 샤엘은 당신에게 이 고급 클럽하우스를 양도하겠다고 제안했다. 이것은 희롱일까, 아니면 진심일까.",
  str_files_story_des_30129 = "세상에는 무수한 감정이 있고, 이는 무수한 색채에 대응한다. 강도 앞에서도 레스터가 여전히 다채로운 색깔을 보여주려 하는 이유는...",
  str_files_story_des_30132 = "북쪽 나라의 거울은 나시리스의 손으로 돌아왔지만, 다시 거울의 반대편을 마주하려면 그녀는 아직 용기가 필요하다...",
  str_files_story_des_35042 = "미트라는 최근 계속 무기력하고, 잠도 좀 부족해 보인다. 하지만 그녀는 여전히 당신에게 맡길 일이 없냐고 묻는다...",
  str_files_story_des_30133 = "아킬레스는 단말기 사용법을 배우고, 당신을 별의 전사들의 연회에 초대했다. 그것은 무척이나 즐거운 밤이었다...",
  str_files_audio_author_1602411 = "오구라 유이",
  str_files_basic_desc_1602411 = "[이름] 페피타\n[별명] 자유로운 이단아\n[성별] 여\n[키] 168cm\n[생일] 불명\n[출생지] 일루미나 모 지하성\n[속성] 불\n[소속 조직] 진리의 결사\n[전투 방식] 빛나는 심장",
  str_files_intial_report_1602411 = "페피타가 콜로서스에 온 첫날은 정말 기억이 뚜렷하게 남아있어... 그날, 페피타가 갑자기 찾아와서는 %s하고 놀고 싶어서 온 거라고 했어. 간신히 협조를 받아서 등록 절차를 마쳤는데, 또 갑자기 빈손으로는 실례인 것 같으니까 사람들한테 식사 대접을 하고 싶다지 뭐야. 그러고는 손뼉을 치고 슥 가버렸어. 그렇게 왔다가 중간에 가버린 사람은 진짜 처음이었다니까. 뭐가 어떻게 된 건지 모르겠더라고. 그러고 여섯 시가 되자마자 갑자기 단정한 옷차림의 하인들이 잔뜩 와서는 엄청 호화로운 음식을 가지고 콜로서스에 들어왔어. 페피타는 어깨를 으쓱거리면서 뒤에서 걸어오더라고.\n\n그날 저녁은 진짜 풍성하고 맛있었어. 다들 페피타한테 엄청 좋은 인상을 받았고 말이야.\n\n...뭐, 그다음 날 신문 제목에 「갑자기 사라진 백야성 귀족의 저녁식사! 사기꾼 집단의 범행 혐의로 추정」이라는 기사가 나오긴 했는데... 그건 우리랑 전혀 상관없잖아...\n\n...그렇지? 괜찮겠지?\n\n──바이스",
  str_files_pet_files1_1602411 = "내 「아버지」란 사람 말인데... 한때 난 그 사람을 존경했었어. 웃기지? 나름대로 사회적 지위가 있고, 자상한 성격에, 꽤 지적이었거든. 난 그 사람을 이 세상 최고의 아버지라고 생각했었어. 아이에게 손찌검이나 하는 남의 집 부모와는 다르다고 말이야. 하지만 나중의 일로 내 두 눈이 장식이었다는 게 증명됐어. 시련을 겪기 전까지 인간의 본질이 얼마나 썩었는지 넌 절대 모를 거야.\n\n지금 생각해 보면 그 사람의 나약함과 혐오스러운 면모는 이미 징조가 있었어. 어느 날 그 사람 친구가 아이를 데리고 우리 집에 놀러 왔어. 그놈은 엄마가 나한테 준 새 장난감을 마음대로 꺼내고, 심지어 더럽혔어! 난 엄청나게 화가 났는데, 아빠는 오히려 날 구석으로 끌고 가서 질책했어. 그놈이랑은 싸우면 안 되고, 웃는 얼굴로 너그럽게 굴라는 거야. 왜냐하면 그 친구가 군에서 계급이 더 높았으니까! 난 화가 났어. 하지만 아버지를 믿기도 했어. 그 사람 말은 뭐든지 맞다고 믿었고, 내가 버릇없이 굴면 안 된다고 생각했지... 망할! 나한테도 그런 억울한 시절이 있었다니, 울화통이 터질 지경이야!",
  str_files_pet_files2_1602411 = "난 선천적으로 심장이 안 좋았는데, 그 남자는 그런 거 신경 안 썼어. 그 사람은 자기 보신과 위원회 입성을 위해서 어머니를 죽게 만들었고, 나까지 위원회에 「헌납」했어. 난 실험체가 됐지만, 그 사람은 신경도 쓰지 않았어. 하, 내가 그걸로 주저앉았을 거라 생각하지 마. 난 그 사람의 본성을 간파했고, 마음속 깊은 곳에서 불길이 타올랐어. 아무도 이 페피타 님의 빛나는 인생을 망칠 수 없다고! 그 남자도, 위원회도 절대 그럴 순 없다고. 실험자가 날 얼마나 괴롭히든, 난 계속 버티면서 기회를 기다렸어. 그리고 어느 날, 눈을 떴을 때, 난 놈들이 인공 심장으로 내 심장으로 대체했단 걸 알았어.\n\n그렇게 난 더는 정상적인 오로리안이 아니게 되어 버렸던 거야... 몸의 일부가 기계와 교체되고, 심지어 타인에 의해 제어됐지. 그놈들은 말로는 좋은 사람인 척하면서, 날 치료해 주려고, 강하게 만들어 주려고 그랬다고 했지만, 난 그런 가식적인 말과 얼굴엔 진저리가 났어. 그중에서 딱 벨리사리아만 조금 달랐지만... 하아? 당연히 그 사람이 날 진심으로 생각해 줬다는 말은 아니지. 위원회의 진짜 목적을 솔직하게 말해준 게 그 사람뿐이었거든. 인공 심장을 가지고 「중요한 실험체」인 날 제어하고 싶다는 거 말이야. 아하하, 내가 순순히 말을 들을 리가 없다는 걸 놈들도 알고 있었던 거지!",
  str_files_pet_files3_1602411 = "나중에 난 일루미나에서 도망쳤어... 뭘 놀라고 그래? 당연한 거 아냐? 처음에 갔던 건 움브라톤이었어. 일루미나에서 갑갑한 날들을 보냈으니까, 마음껏 놀고 싶었거든! 복장까지 바꾸고, 「페피타·파이루즈 아가씨」가 되어 움브라톤에서 주목의 대상이 됐어. 하! 대충 지은 성이었는데, 그 사람들은 진짜인 줄 알고 얼마나 아부를 떨던지, 네가 그 꼴을 봤어야 된다니까.\n그러다 사람 조종하는 재미도 금방 질려버렸고, 너무 지루해서 새로운 즐거움을 찾고 있었어. 그러다 아이디어가 떠올랐지. 망토를 걸치고, 목소리 잔뜩 깔고, 진리의 결사의 사기꾼 연기를... 크흠... 무슨 소린지 알지? 그리고 이번엔 대성공이었어. 역시 이 페피타 님의 놀이 재능은 천재적이라니까! 그 뒤에? 빅토리아 님이 내 앞에 나타나셨던 거야.\n그분은 나한테서 길을 찾는 혼란과 열정이 느껴진다고 하셨어. 그리고 진리의 결사에 들어오면 이곳에서만 타오를 수 있는 불꽃이 있다고 하셨지.\n난 곧바로 들어가겠다고 대답했어. 진리를 찾는 건 무척 재미있을 것 같았거든. 그리고... 계속 죽치고 있다간 움브라톤에「도」 날 추종하는 새로운 교파가 탄생하게 생겼으니까!",
  str_files_pet_files4_1602411 = "진리의 결사에 들어간 뒤로, 난 그 사람들이랑 같이 어둠의 밑바닥을 한 번 탐색했어. 그때 발생한 일은... 아니, 아주 많은 일들은 내가 자신의 가치를 확신하게 만들었어. 난 어둠의 밑바닥 같은 죽음의 땅에서도 영향을 받지 않고 자유롭게 행동할 수 있었어. 어쩐지 어쩐지 그 늙은이들이 그렇게 날 연구하고 싶어 하더라니! 아하하, 놈들이 날 포기하지 않을 거란 건 알아. 내 능력은 놈들한테 엄청난 가치가 있거든. 무슨 수를 써서라도 날 데리고 돌아가서 가이드로 삼든지, 아니면 날 실험대 위에 묶겠지!\n\n흥, 내가 무서워서 도망칠 줄 알았어? 아니, 난 무조건 돌아갈 거야! 내 원래 심장도 거기 있고, 내가 복수할 상대도 거기 있으니까! 내 심장을 되찾으면 다시 완전해질 수 있고, 다시는 그 누구도 날 조종하지 못해. 그때가 되면 난 그 남자를 죽이고, 어머니의 원수를 갚을 수 있어. 그리고 내 인생도... 확실하게 해방되겠지.",
  str_files_story_title_35043 = "성스러운 심장",
  str_files_story_des_35043 = "당시 페피타의 「신도」들은 지금까지도 그녀를 잊지 못하고 있다...",
  str_files_story_title_30134 = "뒤늦은 좋은 아침",
  str_files_story_des_30134 = "당신은 로렐라이가 새로 인수한 테마 호텔의 체험 임무를 완수했지만, 아직 로렐라이의 검수를 받지 못했고, 이에 그녀의 방으로 가서 상황을 파악하기로 결정했다..."
}
